22	    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kBFloat16 || self.scalar_type() == at::kFloat,
23	                "foreach_tan: only float16, bfloat16 and float32 are supported, got ", self.scalar_type());
