26	
27	    int64_t totalLength = self.numel();
28	    if (totalLength == 0) {
29	        return output;
30	    }
31	
32	    int64_t dtypeSize = self.element_size();
33	
34	    // ---- 获取硬件参数 ----
35	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
36	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
37	    uint64_t ubSize;
38	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
39	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
40	
41	    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
42	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
43	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
44	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
45	
46	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
47	    int64_t formerNum = usedCoreNum - 1;
48	    int64_t formerLength = totalLengthCoreAlign;
49	    int64_t tailLength = totalLength - formerNum * formerLength;
50	
51	    // ---- UB 级 tiling (核内切分) ----
52	    // bufferCoefficient = 每元素在 UB 中总占用字节
53	    // 单输入单输出 + double buffer + fp16/bf16 升精度
54	    //   fp32: 2 queues * 2(double buf) * 4B + 1 temp * 4B = 20
55	    //   fp16/bf16: 2 queues * 2(double buf) * 2B + 2 temp * 4B = 16
56	    int64_t bufferCoefficient = (dtypeSize == 4) ? 20 : 16;
57	    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
58	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
59	    if (dtypeSize == 0) { dtypeSize = 1; }
60	    int64_t alignElements = 32 / dtypeSize;
61	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
62	
63	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
64	
65	    // EXEC_KERNEL_CMD: 所有参数必须是左值
66	    int64_t tailLengthLval = tailLength;
67	    int64_t tileLengthLval = tileLength;
68	    int64_t dtypeSizeLval = dtypeSize;
69	
70	    EXEC_KERNEL_CMD(foreach_tan, blockDim,
71	                    self, output,
72	                    formerNum, formerLength, tailLengthLval, tileLengthLval, dtypeSizeLval);
73	
74	    return output;
