14	
15	constexpr int32_t BUFFER_NUM = 2;
16	
17	template <typename T>
18	class KernelForeachTan {
19	public:
20	    __aicore__ inline KernelForeachTan() {}
21	
22	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
23	                                int64_t formerNum, int64_t formerLength,
24	                                int64_t tailLength, int64_t tileLength)
25	    {
26	        int64_t blockIdx = AscendC::GetBlockIdx();
27	
28	        if (blockIdx < formerNum) {
29	            this->blockLength = formerLength;
30	            int64_t offset = formerLength * blockIdx;
31	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
32	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
33	        } else {
34	            this->blockLength = tailLength;
35	            int64_t tailIdx = blockIdx - formerNum;
36	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
37	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
38	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
39	        }
40	
41	        this->tileLength = tileLength;
42	
43	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
44	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
45	
46	        if constexpr (sizeof(T) != sizeof(float)) {
47	            pipe.InitBuffer(tmpBufX, tileLength * sizeof(float));
48	            pipe.InitBuffer(tmpBufY, tileLength * sizeof(float));
49	            pipe.InitBuffer(tmpBufZ, tileLength * sizeof(float));
50	        } else {
51	            pipe.InitBuffer(tmpBufY, tileLength * sizeof(T));
52	            pipe.InitBuffer(tmpBufZ, tileLength * sizeof(T));
53	        }
54	    }
55	
56	    __aicore__ inline void Process()
57	    {
58	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
59	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
60	
61	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
62	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
63	
64	        for (int64_t i = 0; i < tileNum - 1; ++i) {
65	            CopyIn(i, this->tileLength);
66	            Compute(i, this->tileLength);
67	            CopyOut(i, this->tileLength);
68	        }
69	        if (tileNum > 0) {
70	            CopyIn(tileNum - 1, alignedTailLen);
71	            Compute(tileNum - 1, alignedTailLen);
72	            CopyOut(tileNum - 1, alignedTailLen);
73	        }
74	    }
75	
76	private:
77	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
78	    {
79	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
80	        AscendC::DataCopy(xLocal, xGm[progress * this->tileLength], curTileLength);
81	        inQueueX.EnQue(xLocal);
82	    }
83	
84	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
85	    {
86	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
87	        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
88	
89	        if constexpr (sizeof(T) == sizeof(float)) {
90	            // FP32: sin(x) -> tmpY, cos(x) -> tmpZ, tmpY / tmpZ -> yLocal
91	            AscendC::LocalTensor<float> sinLocal = tmpBufY.Get<float>();
92	            AscendC::LocalTensor<float> cosLocal = tmpBufZ.Get<float>();
93	
94	            AscendC::Sin(sinLocal, xLocal, static_cast<uint32_t>(curTileLength));
95	            AscendC::Cos(cosLocal, xLocal, static_cast<uint32_t>(curTileLength));
96	            AscendC::Div(yLocal, sinLocal, cosLocal, static_cast<uint32_t>(curTileLength));
97	        } else {
98	            // FP16/BF16: Cast to FP32 -> sin -> tmpY, cos -> tmpZ, div -> tmpY, Cast back
99	            AscendC::LocalTensor<float> xFp32 = tmpBufX.Get<float>();
100	            AscendC::LocalTensor<float> sinFp32 = tmpBufY.Get<float>();
101	            AscendC::LocalTensor<float> cosFp32 = tmpBufZ.Get<float>();
102	
103	            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
104	            AscendC::Sin(sinFp32, xFp32, static_cast<uint32_t>(curTileLength));
105	            AscendC::Cos(cosFp32, xFp32, static_cast<uint32_t>(curTileLength));
106	            AscendC::Div(sinFp32, sinFp32, cosFp32, static_cast<uint32_t>(curTileLength));
107	            AscendC::Cast(yLocal, sinFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
108	        }
109	
110	        outQueueY.EnQue<T>(yLocal);
111	        inQueueX.FreeTensor(xLocal);
112	    }
113	
114	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
115	    {
116	        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
117	        AscendC::DataCopy(yGm[progress * this->tileLength], yLocal, curTileLength);
118	        outQueueY.FreeTensor(yLocal);
119	    }
120	
