122	    AscendC::TPipe pipe;
123	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
124	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
125	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufX;
126	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufY;
127	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufZ;
128	    AscendC::GlobalTensor<T> xGm;
129	    AscendC::GlobalTensor<T> yGm;
130	    int64_t blockLength;
131	    int64_t tileLength;
132	};
