                                                     int64_t tailLength, int64_t tileLength,
                                                     int64_t dtypeSize)
{
    if (dtypeSize == 2) {
        KernelForeachTan<half> op;
        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else {
        KernelForeachTan<float> op;
        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    }
}
